-- ============================================
-- LUMA — Thème 10 : LONG 2/3 x4 — Une affaire qui implique un proche du personnage
-- ============================================


update scenarios set content = '{"characters": {"partner": "votre collègue", "daniel": "Daniel", "victor": "Victor", "captain": "le capitaine", "you_thought": "narration"}, "start_node": "n1", "nodes": {"n1": {"speaker": "partner", "text": "The evidence from the fraud case... it points toward someone close to you. I''m sorry.", "text_fr": "Les preuves de l''affaire de fraude... elles pointent vers quelqu''un de proche de vous. Je suis désolé.", "choices": [{"text": "Who exactly are we talking about?", "text_fr": "De qui exactement on parle ?", "next": "n2"}, {"text": "Show me the evidence. I need to see it myself.", "text_fr": "Montrez-moi les preuves. J''ai besoin de les voir moi-même.", "next": "n2b"}]}, "n2": {"speaker": "partner", "text": "Your old friend, Daniel. The financial trail leads directly to his company.", "text_fr": "Votre vieil ami, Daniel. La piste financière mène directement à son entreprise.", "choices": [{"text": "That can''t be right. Daniel wouldn''t do something like this.", "text_fr": "Ça peut pas être vrai. Daniel ferait jamais un truc pareil.", "next": "n3"}, {"text": "I need to see this for myself before I believe it.", "text_fr": "J''ai besoin de voir ça moi-même avant d''y croire.", "next": "n3"}]}, "n2b": {"speaker": "partner", "text": "(Shows documents) Look at the transaction dates and the shell company names.", "text_fr": "(Montre des documents) Regardez les dates de transaction et les noms des sociétés écrans.", "choices": [{"text": "(Studies the documents carefully, hoping for another explanation.)", "text_fr": "(Étudie les documents attentivement, espérant une autre explication.)", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(The evidence is troublingly clear — but you''ve known Daniel for fifteen years.)", "text_fr": "(Les preuves sont troublement claires — mais vous connaissez Daniel depuis quinze ans.)", "choices": [{"text": "I have to talk to him directly, before this goes any further.", "text_fr": "Je dois lui parler directement, avant que ça aille plus loin.", "next": "n4"}, {"text": "I should recuse myself from this case — I''m too close to it.", "text_fr": "Je devrais me retirer de cette affaire — je suis trop proche.", "next": "n4b"}]}, "n4": {"speaker": "daniel", "text": "(Confused, then alarmed) Wait, what? Fraud charges? This is insane, I didn''t do this!", "text_fr": "(Confus, puis alarmé) Attendez, quoi ? Des accusations de fraude ? C''est fou, j''ai rien fait !", "choices": [{"text": "The evidence points to your company, Daniel. Help me understand.", "text_fr": "Les preuves pointent vers votre entreprise, Daniel. Aidez-moi à comprendre.", "next": "n5"}]}, "n4b": {"speaker": "captain", "text": "I understand the conflict, but we need your expertise on this. Can you stay objective?", "text_fr": "Je comprends le conflit, mais on a besoin de votre expertise là-dessus. Vous pouvez rester objectif ?", "choices": [{"text": "I believe I can, but I''ll need a colleague to double-check my work throughout.", "text_fr": "Je pense pouvoir, mais j''aurai besoin qu''un collègue vérifie mon travail tout du long.", "next": "n5"}]}, "n5": {"speaker": "daniel", "text": "Someone''s been using my company''s name — I swear, I had no idea about any of this!", "text_fr": "Quelqu''un a utilisé le nom de mon entreprise — je jure, j''avais aucune idée de tout ça !", "choices": [{"text": "Who else has access to your company''s financial systems?", "text_fr": "Qui d''autre a accès aux systèmes financiers de votre entreprise ?", "next": "n6"}]}, "n6": {"speaker": "daniel", "text": "My business partner, Victor. He handles most of the financial side, honestly.", "text_fr": "Mon associé, Victor. Il gère la plupart du côté financier, honnêtement.", "choices": [{"text": "We''ll need to speak with Victor immediately.", "text_fr": "On devra parler à Victor immédiatement.", "next": "n7"}]}, "n7": {"speaker": "victor", "text": "(Calm, too calm) Daniel''s business? I only handle what he asks me to handle.", "text_fr": "(Calme, trop calme) L''entreprise de Daniel ? Je gère seulement ce qu''il me demande de gérer.", "choices": [{"text": "That''s not quite what Daniel told us. Care to explain the discrepancy?", "text_fr": "C''est pas tout à fait ce que Daniel nous a dit. Vous voulez expliquer la différence ?", "next": "n8"}]}, "n8": {"speaker": "victor", "text": "(Slight crack in composure) Perhaps I''ve taken some... liberties, for the company''s benefit.", "text_fr": "(Léger craquement dans son sang-froid) Peut-être que j''ai pris quelques... libertés, pour le bénéfice de l''entreprise.", "choices": [{"text": "Liberties that funneled money into shell companies under Daniel''s name?", "text_fr": "Des libertés qui ont canalisé de l''argent vers des sociétés écrans sous le nom de Daniel ?", "next": "n9"}]}, "n9": {"speaker": "victor", "text": "(Defensive) Daniel wasn''t paying attention to the finances closely enough. Someone had to make real decisions.", "text_fr": "(Sur la défensive) Daniel ne prêtait pas assez attention aux finances. Quelqu''un devait prendre de vraies décisions.", "choices": [{"text": "So you used his trust and his company''s name for your own gain.", "text_fr": "Donc vous avez utilisé sa confiance et le nom de son entreprise pour votre propre gain.", "next": "n10"}]}, "n10": {"speaker": "victor", "text": "(Silence, then a resigned sigh) Yes. It was easier than starting my own company from scratch.", "text_fr": "(Silence, puis un soupir résigné) Oui. C''était plus facile que de démarrer ma propre entreprise à partir de rien.", "choices": [{"text": "Daniel deserves to hear this directly from you.", "text_fr": "Daniel mérite d''entendre ça directement de vous.", "next": "n11"}]}, "n11": {"speaker": "daniel", "text": "(Devastated) Victor... I trusted you completely. How could you do this to me?", "text_fr": "(Dévasté) Victor... je te faisais totalement confiance. Comment t''as pu me faire ça ?", "choices": [{"text": "(Give Daniel a moment before continuing with the arrest procedure.)", "text_fr": "(Laisse un moment à Daniel avant de continuer la procédure d''arrestation.)", "next": "n12"}]}, "n12": {"speaker": "daniel", "text": "(To you) Thank you for not assuming the worst about me, even when the evidence looked bad.", "text_fr": "(À toi) Merci de ne pas avoir supposé le pire de moi, même quand les preuves semblaient mauvaises.", "choices": [{"text": "I know you, Daniel. That counted for something, even against strong evidence.", "text_fr": "Je te connais, Daniel. Ça comptait pour quelque chose, même face à des preuves solides.", "next": "end_cleared"}]}, "end_cleared": {"speaker": "captain", "text": "Good work separating personal loyalty from professional integrity. Not everyone can do that.", "text_fr": "Beau travail pour séparer la loyauté personnelle de l''intégrité professionnelle. Tout le monde ne peut pas faire ça.", "end": true, "ending_label": "Ami innocenté, vrai coupable démasqué 👥⚖️"}}}'::jsonb, is_playable = true
where title = 'Une affaire qui implique un proche du personnage'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
